# Define a function to check if a number is a palindrome
def is_palindrome(n):
    return str(n) == str(n)[::-1]

# Define a function to check if a number is a power of two
def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

# Define a function to check if a number is a power of two and a palindrome
def is_power_and_palindrome(n):
    return is_power_of_two(n) and is_palindrome(n)

# Test the function
print(is_power_and_palindrome(16))  # True
print(is_power_and_palindrome(19))  # False
print(is_power_and_palindrome(8))   # True
print(is_power_and_palindrome(9))   # False

def translate_to_english(text):
    translation = {
        "今天": "today",
        "他": "he",
        "每天": "every day",
        "坚": "strong",
        "迟": "late",
        "锻炼": "exercise",
        "身体": "body"
    }
    return ' '.join(translation.get(word, word) for word in text.split())

print(translate_to_english("今天，他每天坚迟锻炼身体。"))

